mapper.update:
UPDATE incident SET last_event_id=#{eventId},event_count=event_count+1,
                    last_event_at=GREATEST(last_event_at,#{now}),
                    summary=COALESCE(#{summary},summary),lock_version=lock_version+1,
                    updated_at=#{now},updated_by_type='INTEGRATION',updated_by_id=#{integrationId}
                WHERE tenant_id=#{tenantId} AND incident_id=#{active.incidentId} AND status='ACTIVE' AND lock_version=#{active.lockVersion}

UPDATE incident SET status='RECOVERED',last_event_id=#{eventId},event_count=event_count+1,
                    last_event_at=GREATEST(last_event_at,#{now}),
                    recovered_at=GREATEST(last_event_at,#{now}),recovery_event_id=#{eventId},
                    summary=COALESCE(#{summary},summary),lock_version=lock_version+1,
                    updated_at=#{now},updated_by_type='INTEGRATION',updated_by_id=#{integrationId}
                WHERE tenant_id=#{tenantId} AND incident_id=#{active.incidentId} AND status='ACTIVE' AND lock_version=#{active.lockVersion}

mapper.select:
SELECT n.incident_id,n.fingerprint,n.generation_no,n.status,n.event_count,n.opened_at,n.last_event_at,n.recovered_at,n.summary,n.lock_version,n.created_at,n.updated_at,e.alert_cycle_ref AS cycle_ref
FROM incident n JOIN alert_event e ON e.tenant_id=n.tenant_id AND e.alert_event_id=n.first_event_id LEFT JOIN incident_ticket_link l ON l.tenant_id=n.tenant_id AND l.incident_id=n.incident_id WHERE n.tenant_id=#{tenantId}
AND n.status=#{filter.status}
AND n.fingerprint=#{filter.fingerprint}
AND l.status=#{filter.ticketLinkStatus}
AND n.opened_at >= #{filter.openedFrom}
AND n.opened_at <= #{filter.openedTo}
AND ( >< #{cursorTime} OR (=#{cursorTime} AND n.incident_id >< #{cursorId}))
ORDER BY  ASCDESC,n.incident_id ASCDESC LIMIT #{limit}
